export const metadata: Metadata = {
  title: "Pricing",
  description: `Websites ${WEB_FROM}, the audit at ${SEO_AUDIT}, the ongoing plan at ${SEO_ONGOING}. Fixed numbers, agreed in writing.`,
  alternates: { canonical: "https://solaisoft.com/pricing" },
};

const jsonLd = {
